//! Downloadable models, pinned to Hugging Face commits with SHA-256 hashes.
//! `catalog.json` is generated by `scripts/gen_catalog.py`.

use std::path::{Path, PathBuf};
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ModelKind {
    Stt,
    Vad,
    Multilingual,
    Llm,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ModelFile {
    pub url: String,
    /// File name inside the model's directory.
    pub name: String,
    pub size: u64,
    pub sha256: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ModelSpec {
    pub id: String,
    pub kind: ModelKind,
    pub name: String,
    pub description: String,
    /// Estimated resident memory when loaded.
    pub ram_mb: u64,
    pub files: Vec<ModelFile>,
}

impl ModelSpec {
    pub fn download_size(&self) -> u64 {
        self.files.iter().map(|f| f.size).sum()
    }

    pub fn dir(&self, models_root: &Path) -> PathBuf {
        models_root.join(&self.id)
    }

    /// Installed means every file is present with the expected size. Hashes are
    /// verified at download time, not on every launch.
    pub fn is_installed(&self, models_root: &Path) -> bool {
        let dir = self.dir(models_root);
        self.files.iter().all(|f| std::fs::metadata(dir.join(&f.name)).is_ok_and(|m| m.len() == f.size))
    }
}

pub fn all() -> &'static [ModelSpec] {
    static CATALOG: OnceLock<Vec<ModelSpec>> = OnceLock::new();
    CATALOG.get_or_init(|| serde_json::from_str(include_str!("catalog.json")).expect("catalog.json is valid"))
}

pub fn get(id: &str) -> Option<&'static ModelSpec> {
    all().iter().find(|m| m.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_has_defaults_pinned_to_commits_over_https_from_hugging_face() {
        for id in ["parakeet-tdt-0.6b-v3", "silero-vad", "whisper-large-v3-turbo", "qwen3-4b-instruct-2507"] {
            assert!(get(id).is_some(), "{id} missing");
        }
        for m in all() {
            for f in &m.files {
                assert!(f.url.starts_with("https://huggingface.co/"), "{}", f.url);
                assert!(f.url.contains("/resolve/") && !f.url.contains("/resolve/main/"), "unpinned {}", f.url);
                if f.size > 10_000_000 {
                    assert!(f.sha256.as_ref().is_some_and(|h| h.len() == 64), "large file without hash {}", f.url);
                }
            }
        }
    }

    #[test]
    fn settings_defaults_point_at_catalog_entries() {
        let s = crate::settings::Settings::default();
        assert_eq!(get(&s.stt.model).unwrap().kind, ModelKind::Stt);
        assert_eq!(get(&s.stt.multilingual_model).unwrap().kind, ModelKind::Multilingual);
        assert_eq!(get(&s.cleanup.llm_model).unwrap().kind, ModelKind::Llm);
    }
}
